<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>IdeaForum — Page Not Found</title>
    <meta
      name="description"
      content="IdeaForum 404 page with search, recovery links, and cookie preferences."
    />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700;800&display=swap"
      rel="stylesheet"
    />
    <style>
      :root {
        --bg: #ffffff;
        --surface: #f8fbfc;
        --text: #121212;
        --text-secondary: #4f5e66;
        --muted-link: #777777;
        --line: #d9e2e7;
        --code-bg: #f1f5f7;
        --accent: #0d5c73;
        --accent-hover: #0a495c;
        --focus-ring: rgba(13, 92, 115, 0.28);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        background: var(--bg);
        color: var(--text);
        font-family: "DM Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem 1.25rem 8rem;
      }

      .content {
        width: min(100%, 44rem);
        text-align: center;
      }

      .logo {
        display: inline-flex;
        align-items: center;
        gap: 0.6rem;
        margin-bottom: 2.4rem;
        text-decoration: none;
        color: #0e3f4f;
        font-weight: 700;
        letter-spacing: 0.01em;
      }

      .logo-mark {
        width: 2rem;
        height: 2rem;
        border-radius: 0.55rem;
        background: linear-gradient(155deg, #0b6f89, #0f4556);
        display: grid;
        place-items: center;
        color: #f2fbff;
        font-weight: 800;
        font-size: 0.86rem;
      }

      .title {
        margin: 0;
        font-size: clamp(1.9rem, 4vw, 2.65rem);
        letter-spacing: -0.02em;
        font-weight: 700;
      }

      .subtitle {
        margin: 0.75rem auto 2rem;
        color: var(--text-secondary);
        line-height: 1.55;
        max-width: 34rem;
        font-size: clamp(1rem, 2.1vw, 1.075rem);
      }

      .search-wrap {
        margin: 0 auto 2rem;
        width: min(100%, 36rem);
      }

      .search-form {
        position: relative;
      }

      .search-input {
        width: 100%;
        height: 3.35rem;
        border: 1px solid #c8d6dd;
        border-radius: 0.75rem;
        font-size: 1rem;
        padding: 0 3.25rem 0 1rem;
        color: var(--text);
        background: var(--surface);
      }

      .search-input::placeholder {
        color: #6d7f88;
      }

      .search-input:focus-visible,
      .action-link:focus-visible,
      .logo:focus-visible,
      .cookie-btn:focus-visible,
      .prefs-button:focus-visible,
      .prefs-close:focus-visible,
      .privacy-link:focus-visible,
      .toggle:focus-within {
        outline: 2px solid var(--focus-ring);
        outline-offset: 2px;
      }

      .search-btn {
        position: absolute;
        top: 50%;
        right: 0.5rem;
        transform: translateY(-50%);
        width: 2.4rem;
        height: 2.4rem;
        border: none;
        border-radius: 0.55rem;
        display: grid;
        place-items: center;
        background: transparent;
        color: #4e6570;
        cursor: pointer;
      }

      .search-btn:hover {
        color: #2f4955;
        background: #eaf1f4;
      }

      .code-block {
        margin: 0 auto;
        width: min(100%, 36rem);
        background: var(--code-bg);
        border-radius: 0.65rem;
        padding: 0.75rem 1rem;
        color: #62727a;
        font-size: 0.9rem;
        font-weight: 500;
        letter-spacing: 0.02em;
      }

      .divider {
        margin: 1.1rem auto 1.5rem;
        width: min(100%, 36rem);
        border: 0;
        border-top: 1px solid var(--line);
      }

      .next-title {
        margin: 0 0 0.7rem;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .actions {
        margin: 0;
        padding: 0;
        list-style: none;
        display: grid;
        gap: 0.45rem;
      }

      .action-link {
        color: var(--muted-link);
        text-decoration: underline;
        text-underline-offset: 0.2em;
        transition: color 180ms ease;
      }

      .action-link:hover {
        color: #4d4d4d;
      }

      .banner {
        position: fixed;
        left: 0;
        right: 0;
        bottom: 0;
        border-top: 1px solid var(--line);
        background: #ffffff;
        padding: 0.95rem 1rem;
        z-index: 20;
      }

      .banner-inner {
        width: min(100%, 68rem);
        margin: 0 auto;
        display: flex;
        flex-direction: column;
        gap: 0.8rem;
      }

      .banner p {
        margin: 0;
        font-size: 0.9rem;
        line-height: 1.45;
        color: #4d5c64;
      }

      .privacy-link {
        color: #52656e;
      }

      .cookie-btn {
        align-self: flex-start;
        border: 1px solid #bfd1d9;
        background: #f8fcfe;
        color: var(--accent);
        border-radius: 0.55rem;
        height: 2.35rem;
        padding: 0 1rem;
        font-weight: 600;
        cursor: pointer;
      }

      .cookie-btn:hover {
        background: #eff7fa;
        color: var(--accent-hover);
      }

      dialog {
        border: 1px solid #c6d6de;
        border-radius: 0.9rem;
        width: min(92vw, 34rem);
        padding: 0;
      }

      dialog::backdrop {
        background: rgba(7, 30, 39, 0.35);
      }

      .prefs {
        padding: 1.1rem 1.1rem 1rem;
      }

      .prefs-head {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 1rem;
        margin-bottom: 0.45rem;
      }

      .prefs-head h2 {
        margin: 0;
        font-size: 1.05rem;
      }

      .prefs-close {
        border: none;
        background: transparent;
        font-size: 1.2rem;
        cursor: pointer;
        color: #5a6a72;
      }

      .prefs-copy {
        margin: 0 0 0.85rem;
        color: #5a6770;
        font-size: 0.92rem;
      }

      .toggle {
        display: flex;
        justify-content: space-between;
        align-items: center;
        border: 1px solid #d3dfe5;
        border-radius: 0.65rem;
        padding: 0.7rem 0.8rem;
        margin-bottom: 0.55rem;
      }

      .toggle label {
        font-size: 0.92rem;
        color: #36444b;
      }

      .toggle input {
        accent-color: var(--accent);
      }

      .prefs-button {
        margin-top: 0.5rem;
        border: none;
        background: var(--accent);
        color: #f7fdff;
        border-radius: 0.55rem;
        height: 2.4rem;
        padding: 0 1rem;
        font-weight: 600;
        cursor: pointer;
      }

      .prefs-button:hover {
        background: var(--accent-hover);
      }

      @media (min-width: 720px) {
        .page {
          padding: 3rem 2rem 8.3rem;
        }

        .banner-inner {
          flex-direction: row;
          justify-content: space-between;
          align-items: center;
          gap: 1.5rem;
        }

        .cookie-btn {
          align-self: center;
          flex-shrink: 0;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="content" aria-labelledby="error-heading">
        <a class="logo" href="./index.html" aria-label="IdeaForum homepage">
          <span class="logo-mark" aria-hidden="true">IF</span>
          <span>IdeaForum</span>
        </a>

        <h1 class="title" id="error-heading">Sorry, we can't find that.</h1>
        <p class="subtitle">
          Perhaps we can help you find the content you're looking for:
        </p>

        <div class="search-wrap">
          <form class="search-form" id="searchForm" action="./search.html" method="get" role="search">
            <label for="site-search" class="sr-only" style="position:absolute;left:-9999px;">Search IdeaForum</label>
            <input
              id="site-search"
              class="search-input"
              type="search"
              name="q"
              placeholder="Search IdeaForum..."
              required
            />
            <button class="search-btn" type="submit" aria-label="Search">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                <circle cx="11" cy="11" r="7" stroke="currentColor" stroke-width="2"></circle>
                <path d="M20 20L16.65 16.65" stroke="currentColor" stroke-width="2" stroke-linecap="round"></path>
              </svg>
            </button>
          </form>
        </div>

        <div class="code-block">HTTP Error 404</div>
        <hr class="divider" />

        <section aria-labelledby="next-heading">
          <h2 class="next-title" id="next-heading">What's next?</h2>
          <ul class="actions">
            <li><a class="action-link" href="./home.html">Go to the homepage</a></li>
            <li><a class="action-link" href="./help-desk.html">Visit our Help Desk</a></li>
          </ul>
        </section>
      </section>
    </main>

    <aside class="banner" id="cookieBanner" aria-label="Cookie consent">
      <div class="banner-inner">
        <p>
          This website utilizes technologies such as cookies to enable essential site functionality,
          as well as for analytics, personalization, and targeted advertising. To learn more, view
          the following link:
          <a class="privacy-link" href="./privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
        </p>
        <button class="cookie-btn" id="openPrefs" type="button">Manage Preferences</button>
      </div>
    </aside>

    <dialog id="prefsModal" aria-labelledby="prefsTitle">
      <form method="dialog" class="prefs" id="prefsForm">
        <div class="prefs-head">
          <h2 id="prefsTitle">Cookie Preferences</h2>
          <button type="button" class="prefs-close" id="closePrefs" aria-label="Close preferences">×</button>
        </div>
        <p class="prefs-copy">Choose which categories IdeaForum can use while you browse.</p>

        <div class="toggle">
          <label for="essential">Essential cookies (always on)</label>
          <input id="essential" type="checkbox" checked disabled />
        </div>
        <div class="toggle">
          <label for="analytics">Analytics cookies</label>
          <input id="analytics" type="checkbox" checked />
        </div>
        <div class="toggle">
          <label for="personalization">Personalization cookies</label>
          <input id="personalization" type="checkbox" />
        </div>
        <div class="toggle">
          <label for="advertising">Targeted advertising cookies</label>
          <input id="advertising" type="checkbox" />
        </div>

        <button class="prefs-button" type="submit">Save Preferences</button>
      </form>
    </dialog>

    <script>
      const banner = document.getElementById("cookieBanner");
      const modal = document.getElementById("prefsModal");
      const openPrefs = document.getElementById("openPrefs");
      const closePrefs = document.getElementById("closePrefs");
      const prefsForm = document.getElementById("prefsForm");

      const consentState = localStorage.getItem("ideaforum-cookie-consent");
      if (consentState === "saved") {
        banner.hidden = true;
      }

      openPrefs.addEventListener("click", () => {
        modal.showModal();
      });

      closePrefs.addEventListener("click", () => {
        modal.close();
      });

      prefsForm.addEventListener("submit", () => {
        localStorage.setItem("ideaforum-cookie-consent", "saved");
        banner.hidden = true;
        modal.close();
      });

      const searchForm = document.getElementById("searchForm");
      searchForm.addEventListener("submit", (event) => {
        const input = document.getElementById("site-search");
        const query = input.value.trim();

        if (!query) {
          event.preventDefault();
          input.focus();
          return;
        }

        event.preventDefault();
        window.location.href = `./search.html?q=${encodeURIComponent(query)}`;
      });
    </script>
  </body>
</html>
