          <input id="analytics" type="checkbox" checked />
        </div>
        <div class="toggle">
          <label for="personalization">Personalization cookies</label>
          <input id="personalization" type="checkbox" />
        </div>
        <div class="toggle">
          <label for="advertising">Targeted advertising cookies</label>
          <input id="advertising" type="checkbox" />
        </div>

        <button class="prefs-button" type="submit">Save Preferences</button>
      </form>
    </dialog>

    <script>
      const banner = document.getElementById("cookieBanner");
      const modal = document.getElementById("prefsModal");
      const openPrefs = document.getElementById("openPrefs");
      const closePrefs = document.getElementById("closePrefs");
      const prefsForm = document.getElementById("prefsForm");

      const consentState = localStorage.getItem("ideaforum-cookie-consent");
      if (consentState === "saved") {
        banner.hidden = true;
      }

      openPrefs.addEventListener("click", () => {
        modal.showModal();
      });

      closePrefs.addEventListener("click", () => {
        modal.close();
      });

      prefsForm.addEventListener("submit", () => {
        localStorage.setItem("ideaforum-cookie-consent", "saved");
        banner.hidden = true;
        modal.close();
      });

      const searchForm = document.getElementById("searchForm");
      searchForm.addEventListener("submit", (event) => {
        const input = document.getElementById("site-search");
        const query = input.value.trim();

        if (!query) {
          event.preventDefault();
          input.focus();
          return;
        }

        event.preventDefault();
        window.location.href = `./search.html?q=${encodeURIComponent(query)}`;
      });
    </script>
  </body>
</html>
